{
  "name": "@mafdet/mcp",
  "version": "1.7.0",
  "description": "Mafdet AI MCP server — read-only account tools (models, balance, usage, subscription, docs) for Claude Code, Cursor, Codex, OpenCode, and Claude Desktop.",
  "type": "module",
  "license": "MIT",
  "author": "Mafdet AI",
  "homepage": "https://www.mafdet.ai",
  "bugs": {
    "email": "support@mafdet.ai"
  },
  "keywords": [
    "mcp",
    "model-context-protocol",
    "mafdet",
    "ai",
    "llm",
    "claude",
    "cursor",
    "codex",
    "opencode"
  ],
  "bin": {
    "mafdet-mcp": "dist/index.js"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "mcpName": "ai.mafdet/mcp",
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.32.2",
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "@types/node": "^20.19.0",
    "typescript": "6.0.3"
  },
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "lint": "prettier --check \"src/**/*.ts\" \"test/**/*.mjs\" package.json tsconfig.json",
    "test": "pnpm run build && node --test \"test/**/*.test.mjs\"",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  }
}
